```javascript
const { Client, GatewayIntentBits, REST } = require('discord.js');
const { Collection } = require('discord.js-commando');
const { Permissions } = require('discord.js');
const fs = require('fs');

// Chargement du token et des IDs
const { DISCORD_TOKEN, CLIENT_ID, GUILD_ID } = require('./.env');

// Configuration du client Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Configuration des commandes
const commando = new Collection();
const commands = [];
fs.readdirSync('./commands').forEach((file) => {
  const cmd = require(`./commands/${file}`);
  commands.push(cmd.data);
  commando.set(cmd.data.name, cmd);
});

// Configuration du REST client Discord
const rest = new REST({ version: '10' }).setToken(DISCORD_TOKEN);

// Définition de la commande "bannir"
const banCommand = {
  name: 'bannir',
  description: 'Bannir un membre du serveur.',
  type: Discord.ApplicationCommandType.ChatInput,
  options: [
    {
      name: 'membre',
      description: 'Le membre à bannir.',
      type: Discord.ApplicationCommandOptionType.User,
      required: true,
    },
    {
      name: 'raison',
      description: 'La raison du bannissement.',
      type: Discord.ApplicationCommandOptionType.String,
      required: false,
    },
  ],
  execute: async ({ interaction }) => {
    const member = interaction.options.getUser('membre');
    const reason = interaction.options.getString('raison');

    if (!interaction.member.permissions.has(Permissions.FLAGS.BAN_MEMBERS)) {
      return interaction.reply({
        content: 'Vous n\'avez pas la permission de bannir des membres.',
        ephemeral: true,
      });
    }

    if (!member.bannable) {
      return interaction.reply({
        content: 'Je ne peux pas bannir ce membre.',
        ephemeral: true,
      });
    }

    await interaction.guild.members.ban(member, { reason });

    return interaction.reply({
      content: `Le membre ${member.user.tag} a été banni avec la raison "${reason || 'Aucune raison spécifiée'}"`,
    });
  },
};

// Chargement des commandes
(async () => {
  try {
    await rest.put(Discord Routes.applicationCommands(CLIENT_ID), { body: commands });
    console.log('Commandes chargées avec succès.');
  } catch (error) {
    console.error(error);
  }
})();

// Écoute des événements du client Discord
client.on('ready', () => {
  console.log(`Bot Discord connecté en tant que ${client.user.tag}`);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const command = commando.get(interaction.commandName);
  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({
      content: 'Une erreur est survenue lors de l\'exécution de cette commande.',
      ephemeral: true,
    });
  }
});

client.login(DISCORD_TOKEN);
```

