```python
class Queue:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []

    def is_empty(self):
        return len(self.in_stack) == 0 and len(self.out_stack) == 0

    def enqueue(self, item):
        """
        Ajoute un élément à la queue en le poussant dans la pile d'entrée.
        """
        self.in_stack.append(item)

    def dequeue(self):
        """
        Retire et renvoie l'élément en tête de la queue en poussant les éléments de la pile d'entrée dans la pile de sortie,
        tant qu'il n'y a pas d'élément dans la pile de sortie.
        """
        if len(self.out_stack) == 0:
            while len(self.in_stack) > 0:
                self.out_stack.append(self.in_stack.pop())
        if len(self.out_stack) > 0:
            return self.out_stack.pop()
        else:
            raise Exception("La file d'attente est vide")

    def peek(self):
        """
        Renvoie l'élément en tête de la queue sans le retirer.
        """
        if len(self.out_stack) == 0:
            while len(self.in_stack) > 0:
                self.out_stack.append(self.in_stack.pop())
        if len(self.out_stack) > 0:
            return self.out_stack[-1]
        else:
            raise Exception("La file d'attente est vide")
```

